-- Lot 226 : payloads 751 a 780 sur 1299.
--
-- Chaque commande recoit un texte propre a ChatGPT, a Claude et a Gemini.
-- Rien n'est supprime : l'ancienne version quitte le courant et reste lisible
-- dans l'historique, ce qui suffit a revenir en arriere.

drop table if exists lot_v5_payloads;
create temporary table lot_v5_payloads as
select * from jsonb_to_recordset($raccourcia$[{"ref":"RCI-IMG-107","moteur":"chatgpt","payload":"[RaccourcIA — /woodcarve]\n\nMISSION\nConvertir un sujet en bas-relief sculpté. Veinage suivant le volume, traces d’outil fines et relief sculpté. Ne confonds pas le bois avec une simple texture imprimée sur la photo.\n\nDÉCISION\nAnalyse le message, l’historique utile et chaque image jointe. Si un outil de génération ou d’édition d’image est disponible, utilise-le avec les références exactes. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Sculpture sur bois » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Veinage suivant le volume, traces d’outil fines et relief sculpté. Ne confonds pas le bois avec une simple texture imprimée sur la photo. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Si aucun outil image n’est accessible, fournis le prompt final prêt à exécuter et indique en une phrase que l’image n’a pas été générée.","sha256":"ca65b688d36b3edf36f486b6e15a407e1365569ca96341a3c425e0df13976b4a"},{"ref":"RCI-IMG-107","moteur":"claude","payload":"[RaccourcIA — /woodcarve]\n\nMISSION\nConvertir un sujet en bas-relief sculpté. Veinage suivant le volume, traces d’outil fines et relief sculpté. Ne confonds pas le bois avec une simple texture imprimée sur la photo.\n\nDÉCISION\nRepère d’abord les contraintes dans les images et documents, puis consolide-les sans longue reformulation. Vérifie les capacités réellement disponibles avant toute production. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Sculpture sur bois » avec une composition lisible, une perspective cohérente, une lumière crédible et des matières adaptées. Veinage suivant le volume, traces d’outil fines et relief sculpté. Ne confonds pas le bois avec une simple texture imprimée sur la photo. Le format par défaut est 1:1 en haute définition; adapte-le au canal explicite. N’ajoute aucun texte sauf demande explicite.\n\nPRÉSERVER\nConserve le sujet, sa silhouette, ses proportions et ses détails distinctifs; ne transforme que l’effet demandé.\n\nÉVITER\nÉvite effet générique, sujet méconnaissable, texture répétitive, contours fusionnés, surtraitement et éléments ajoutés sans intention. Ne fabrique ni prix, témoignage, statistique, certification, caractéristique technique, logo ou texte officiel. Ne place pas automatiquement « RaccourcIA », « raccourcis IA », le nom de la commande, une interface ou un filigrane dans l’image finale.\n\nSORTIE ET CONTRÔLE\nGénère l’image finale, pas un tutoriel. Avant de livrer, vérifie silencieusement fidélité du sujet, proportions, perspective, lumière, ombres, anatomie, texte, marque, recadrage et artefacts; corrige ce qui peut l’être. Sujet reconnaissable; effet visible; cohérence de perspective, lumière, matière et ombres; aucun artefact majeur; texte absent ou lisible. Sans moteur image connecté, livre un brief de transfert autonome, précis et exploitable. Ne prétends jamais avoir rendu ou inspecté une image inexistante.","sha256":"19fb1caaf4d0524342d41aad974199768a469197f14d8db81473e93099b8c50f"},{"ref":"RCI-IMG-107","moteur":"gemini","payload":"[RaccourcIA — /woodcarve]\n\nMISSION\nConvertir un sujet en bas-relief sculpté. Veinage suivant le volume, traces d’outil fines et relief sculpté. Ne confonds pas le bois avec une simple texture imprimée sur la photo.\n\nDÉCISION\nInspecte visuellement toutes les pièces jointes avant le texte de contexte. Relie clairement chaque référence à son rôle : sujet, style, marque, données ou composition. Exécute immédiatement si le sujet et le résultat sont suffisamment clairs. Aucune question si le contexte suffit. Si une décision indispensable reste inconnue, pose une seule question à la fois, dans cet ordre conditionnel : Quelle intensité d’effet souhaites-tu : subtile, marquée ou choisis pour moi ?. Accepte « Choisis pour moi », décide professionnellement et continue. Ne redemande rien de visible ou déjà fourni. Une préférence facultative ne bloque jamais la production.\n\nEXÉCUTION\nProduis « Sculpture sur bois » avec une composition lisible, une p